iac_template:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Inputs (non-infrastructure values only)
###############################################################################

variable "project" {
  description = "Project name used for naming and tagging of the governance stack."
  type        = string
  default     = "service-catalog-governance"
}

variable "environment" {
  description = "Environment name (e.g. test, dev, prod) used for tagging."
  type        = string
  default     = "test"
}

variable "external_id" {
  description = "Optional external ID used to further scope the Service Catalog trust policy. Leave null to skip the sts:ExternalId condition."
  type        = string
  default     = null
}

variable "tags" {
  description = "Additional tags merged onto every taggable resource in this stack."
  type        = map(string)
  default     = {}
}

###############################################################################
# Static provider metadata (no pre-existing remote infrastructure)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  common_tags = merge(
    {
      Project     = var.project
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags
  )
}

###############################################################################
# Service Catalog launch-constraint role
###############################################################################

data "aws_iam_policy_document" "service_catalog_assume_role" {
  statement {
    sid     = "AllowServiceCatalogToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["servicecatalog.amazonaws.com"]
    }

    dynamic "condition" {
      for_each = var.external_id == null ? [] : [var.external_id]

      content {
        test     = "StringEquals"
        variable = "sts:ExternalId"
        values   = [condition.value]
      }
    }
  }
}

resource "aws_iam_role" "test_role" {
  name                 = "test_role"
  description          = "Role assumed by AWS Service Catalog when provisioning products via the launch constraint."
  assume_role_policy   = data.aws_iam_policy_document.service_catalog_assume_role.json
  max_session_duration = 3600

  tags = local.common_tags
}

###############################################################################
# Customer managed key for the artifacts bucket (SSE-KMS)
###############################################################################

resource "aws_kms_key" "artifacts" {
  description             = "CMK used to encrypt Service Catalog provisioned product artifacts in the ${aws_s3_bucket.artifacts.bucket} bucket."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = local.common_tags
}

resource "aws_kms_alias" "artifacts" {
  name          = format("alias/%s-%s-artifacts", var.project, var.environment)
  target_key_id = aws_kms_key.artifacts.key_id
}

###############################################################################
# Artifact bucket used by provisioned products
###############################################################################

resource "aws_s3_bucket" "artifacts" {
  bucket        = format("%s-%s-%s-artifacts", var.project, var.environment, data.aws_caller_identity.current.account_id)
  force_destroy = false

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.artifacts.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Scoped launch-constraint policy attached to test_role
###############################################################################

data "aws_iam_policy_document" "launch_constraint" {
  statement {
    sid    = "CloudFormationStackProvisioning"
    effect = "Allow"

    actions = [
      "cloudformation:CreateStack",
      "cloudformation:UpdateStack",
      "cloudformation:DeleteStack",
      "cloudformation:DescribeStacks",
      "cloudformation:DescribeStackEvents",
      "cloudformation:DescribeStackResources",
      "cloudformation:GetTemplate",
      "cloudformation:GetTemplateSummary",
      "cloudformation:ListStackResources",
      "cloudformation:ValidateTemplate",
    ]

    resources = [
      format(
        "arn:%s:cloudformation:%s:%s:stack/*",
        data.aws_partition.current.partition,
        data.aws_region.current.name,
        data.aws_caller_identity.current.account_id,
      ),
    ]
  }

  statement {
    sid    = "ArtifactObjectReadWrite"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:AbortMultipartUpload",
    ]

    resources = [
      format("%s/*", aws_s3_bucket.artifacts.arn),
    ]
  }

  statement {
    sid    = "ArtifactBucketMetadata"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.artifacts.arn,
    ]
  }

  statement {
    sid    = "ArtifactBucketKmsAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.artifacts.arn,
    ]
  }

  statement {
    sid    = "PassRoleToServiceCatalog"
    effect = "Allow"

    actions = [
      "iam:PassRole",
    ]

    resources = [
      aws_iam_role.test_role.arn,
    ]

    condition {
      test     = "StringEquals"
      variable = "iam:PassedToService"
      values   = ["servicecatalog.amazonaws.com"]
    }
  }
}

resource "aws_iam_policy" "launch_constraint" {
  name        = "service-catalog-launch-constraint"
  description = "Scoped permissions used by the Service Catalog launch-constraint role test_role."
  policy      = data.aws_iam_policy_document.launch_constraint.json

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "launch_constraint" {
  role       = aws_iam_role.test_role.name
  policy_arn = aws_iam_policy.launch_constraint.arn
}

###############################################################################
# Governance group with scoped assume-role permissions
###############################################################################

resource "aws_iam_group" "governance" {
  name = "test_group"
  path = "/"
}

data "aws_iam_policy_document" "group_assume_role" {
  statement {
    sid       = "AssumeLaunchConstraintRole"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.test_role.arn]
  }
}

resource "aws_iam_group_policy" "assume_launch_role" {
  name   = "test-group-assume-launch-role"
  group  = aws_iam_group.governance.name
  policy = data.aws_iam_policy_document.group_assume_role.json
}

###############################################################################
# Console-enabled governance user
###############################################################################

resource "aws_iam_user" "governance" {
  name          = "test_user"
  path          = "/"
  force_destroy = true

  tags = local.common_tags
}

# The AWS provider generates the console password internally at apply time and
# exposes it as the computed attribute `password` (only populated when
# `pgp_key` is not set). The value is a first-login temporary credential
# because `password_reset_required` is true.
resource "aws_iam_user_login_profile" "governance" {
  user                    = aws_iam_user.governance.name
  password_length         = 20
  password_reset_required = true
}

resource "aws_iam_group_membership" "governance" {
  name  = "test-group-membership"
  users = [aws_iam_user.governance.name]
  group = aws_iam_group.governance.name
}

###############################################################################
# Outputs
###############################################################################

output "role_name" {
  description = "Name of the Service Catalog launch-constraint role."
  value       = aws_iam_role.test_role.name
}

output "role_arn" {
  description = "ARN of the Service Catalog launch-constraint role (use as the launch constraint)."
  value       = aws_iam_role.test_role.arn
}

output "launch_constraint_policy_arn" {
  description = "ARN of the scoped launch-constraint policy attached to the role."
  value       = aws_iam_policy.launch_constraint.arn
}

output "group_name" {
  description = "Name of the governance IAM group."
  value       = aws_iam_group.governance.name
}

output "group_arn" {
  description = "ARN of the governance IAM group."
  value       = aws_iam_group.governance.arn
}

output "user_name" {
  description = "Name of the console-enabled governance IAM user."
  value       = aws_iam_user.governance.name
}

output "user_arn" {
  description = "ARN of the console-enabled governance IAM user."
  value       = aws_iam_user.governance.arn
}

output "console_login_url" {
  description = "AWS console sign-in URL for the governance user."
  value       = format("https://%s.signin.aws.amazon.com/console", data.aws_caller_identity.current.account_id)
}

output "console_password" {
  description = "Provider-generated first-login password for the governance user. Marked sensitive so it is never written to plan output; the user must reset it on first login."
  value       = aws_iam_user_login_profile.governance.password
  sensitive   = true
}

output "artifact_bucket_name" {
  description = "Name of the S3 bucket used for Service Catalog provisioned product artifacts."
  value       = aws_s3_bucket.artifacts.bucket
}

output "kms_key_arn" {
  description = "ARN of the customer managed key used for artifact bucket encryption."
  value       = aws_kms_key.artifacts.arn
}

output "kms_key_alias" {
  description = "Alias of the customer managed key used for artifact bucket encryption."
  value       = aws_kms_alias.artifacts.name
}

